-- Customer service schema: branches, customers, KYC evidence, status history and the event outbox.
-- Identifiers are UUIDv7 generated by the application. Cross-service references (e.g. the user ids in
-- *_by columns) are plain values: there are no foreign keys to other services' databases.

create table branches
(
    id         uuid primary key,
    code       varchar(20)  not null,
    name       varchar(150) not null,
    region     varchar(100),
    status     varchar(20)  not null default 'ACTIVE',
    created_at timestamptz  not null default now(),
    updated_at timestamptz  not null default now(),
    created_by uuid,
    updated_by uuid,
    version    bigint       not null default 0,
    constraint branches_code_key unique (code),
    -- Codes travel in the JWT "branch" claim; one canonical spelling avoids scoping mismatches.
    constraint branches_code_upper_chk check (code = upper(code)),
    constraint branches_status_chk check (status in ('ACTIVE', 'INACTIVE'))
);

create sequence customer_no_seq start with 100000 increment by 1;

create table customers
(
    id                      uuid primary key,
    customer_no             varchar(30)  not null,
    full_name               varchar(200) not null,
    date_of_birth           date,
    -- The national id itself is never stored: a keyed hash enforces uniqueness, the last digits allow masked display.
    national_id_fingerprint varchar(64)  not null,
    national_id_last4       varchar(4)   not null,
    risk_level              varchar(20)  not null default 'LOW',
    status                  varchar(20)  not null default 'ACTIVE',
    kyc_status              varchar(20)  not null default 'PENDING',
    branch_code             varchar(20)  not null references branches (code),
    created_at              timestamptz  not null default now(),
    updated_at              timestamptz  not null default now(),
    created_by              uuid,
    updated_by              uuid,
    version                 bigint       not null default 0,
    constraint customers_customer_no_key unique (customer_no),
    constraint customers_national_id_key unique (national_id_fingerprint),
    constraint customers_risk_chk check (risk_level in ('LOW', 'MEDIUM', 'HIGH')),
    constraint customers_status_chk check (status in ('ACTIVE', 'BLOCKED', 'CLOSED')),
    constraint customers_kyc_chk check (kyc_status in ('PENDING', 'VERIFIED', 'REJECTED'))
);

-- Branch-scoped, newest-first listing (keyset-friendly: ties broken by id).
create index customers_branch_created_idx on customers (branch_code, created_at desc, id);
create index customers_branch_status_idx on customers (branch_code, status);
-- Prefix search ("starts with") must work regardless of the database collation.
create index customers_name_prefix_idx on customers (lower(full_name) varchar_pattern_ops);
create index customers_no_prefix_idx on customers (customer_no varchar_pattern_ops);

create table kyc_records
(
    id            uuid primary key,
    customer_id   uuid         not null references customers (id),
    document_type varchar(30)  not null,
    document_ref  varchar(120) not null,
    status        varchar(20)  not null default 'PENDING',
    submitted_by  uuid         not null,
    submitted_at  timestamptz  not null default now(),
    reviewed_by   uuid,
    reviewed_at   timestamptz,
    review_notes  varchar(1000),
    version       bigint       not null default 0,
    constraint kyc_records_type_chk check (document_type in
                                           ('NATIONAL_ID', 'PASSPORT', 'DRIVING_LICENSE', 'UTILITY_BILL', 'PROOF_OF_INCOME')),
    constraint kyc_records_status_chk check (status in ('PENDING', 'APPROVED', 'REJECTED')),
    -- A decided record carries who decided and when; a pending one carries neither.
    constraint kyc_records_review_chk check (
        (status = 'PENDING' and reviewed_by is null and reviewed_at is null)
            or (status <> 'PENDING' and reviewed_by is not null and reviewed_at is not null)),
    -- Maker-checker backstop: the application checks this first, the database guarantees it.
    constraint kyc_records_maker_checker_chk check (reviewed_by is null or reviewed_by <> submitted_by)
);

create index kyc_records_customer_idx on kyc_records (customer_id, submitted_at desc);
-- At most one open submission per document type; also closes the double-submit race.
create unique index kyc_records_one_pending_idx on kyc_records (customer_id, document_type) where status = 'PENDING';

-- Append-only audit trail of customer status changes.
create table customer_status_history
(
    id             uuid primary key,
    customer_id    uuid         not null references customers (id),
    from_status    varchar(20)  not null,
    to_status      varchar(20)  not null,
    reason         varchar(500) not null,
    changed_by     uuid         not null,
    changed_at     timestamptz  not null default now(),
    correlation_id varchar(64)
);

create index customer_status_history_customer_idx on customer_status_history (customer_id, changed_at desc);

-- Transactional outbox (ADR-006): rows are written in the same transaction as the business change.
-- A publisher that relays them to the broker is a later step; published_at stays null until then.
create table outbox_events
(
    id             uuid primary key,
    aggregate_type varchar(50)  not null,
    aggregate_id   uuid         not null,
    event_type     varchar(100) not null,
    payload        jsonb        not null,
    correlation_id varchar(64),
    created_at     timestamptz  not null default now(),
    published_at   timestamptz
);

create index outbox_events_unpublished_idx on outbox_events (created_at) where published_at is null;
